const threadId = "01a0c924-e71f-75b0-8a63-8fb96f0f27d3";
let cursor = undefined;
const pages = [];
for (let i = 0; i < 80; i++) {
  const result = await tools.mcp__codex_app__read_thread({
    threadId,
    hostId: "local",
    turnLimit: 10,
    includeOutputs: false,
    maxOutputCharsPerItem: 12000,
    ...(cursor ? { cursor } : {})
  });
  const raw = result.content?.find((b) => b.type === "text")?.text;
  const page = JSON.parse(raw);
  pages.push(page);
  if (!page.hasMore) break;
  cursor = page.nextCursor;
}
store("conversation_pages", pages);
text(`Collected ${pages.length} conversation-history page(s).`);

const pages = load("conversation_pages");
const page = pages?.[0] ?? {};
text(JSON.stringify({
  hasMore: page.hasMore,
  nextCursor: page.nextCursor,
  itemCount: page.items?.length,
  types: page.items?.map((item) => item.type),
  keys: Object.keys(page)
}));

const page = load("conversation_pages")?.[0] ?? {};
text(JSON.stringify({
  page: page.page,
  turnCount: page.turns?.length,
  turns: page.turns?.map((turn) => ({
    id: turn.id,
    keys: Object.keys(turn),
    itemTypes: turn.items?.map((item) => item.type),
    status: turn.status
  }))
}));

const threadId = "01a0c924-e71f-75b0-8a63-8fb96f0f27d3";
let pages = load("conversation_pages") ?? [];
let cursor = pages.at(-1)?.page?.nextCursor;
while (cursor && pages.length < 100) {
  const result = await tools.mcp__codex_app__read_thread({
    threadId,
    hostId: "local",
    turnLimit: 10,
    includeOutputs: false,
    maxOutputCharsPerItem: 12000,
    cursor
  });
  const raw = result.content?.find((b) => b.type === "text")?.text;
  const page = JSON.parse(raw);
  pages.push(page);
  cursor = page.page?.hasMore ? page.page?.nextCursor : undefined;
}
store("conversation_pages", pages);
text(`Collected ${pages.length} history page(s), ${pages.reduce((n, page) => n + (page.turns?.length ?? 0), 0)} turn(s).`);

const pages = load("conversation_pages") ?? [];
const oldest = pages.at(-1)?.turns?.at(-1);
const samples = oldest?.items?.filter((item) => item.type === "userMessage" || item.type === "agentMessage")?.map((item) => ({type:item.type, keys:Object.keys(item), item}));
text(JSON.stringify(samples));

const pages = load("conversation_pages") ?? [];
const turns = pages
  .slice()
  .reverse()
  .flatMap((page) => (page.turns ?? []).slice().reverse());

function redact(value) {
  return value
    .replace(/(WEBBOX_JWT_SECRET\s*[=:]\s*['"]?)[^\s'"]+/gi, "$1[REDACTED]")
    .replace(/(webbox_token(?:=|:\s*['"]?))[^\s;'"]+/gi, "$1[REDACTED]")
    .replace(/(Authorization:\s*Bearer\s+)[^\s]+/gi, "$1[REDACTED]");
}
function messageText(item) {
  if (item.type === "userMessage") {
    return (item.content ?? [])
      .filter((part) => part.type === "text")
      .map((part) => part.text)
      .join("\n");
  }
  return item.text ?? "";
}
const entries = [];
for (const turn of turns) {
  for (const item of turn.items ?? []) {
    if (item.type !== "userMessage" && item.type !== "agentMessage") continue;
    const raw = redact(messageText(item).trim());
    if (!raw) continue;
    const speaker = item.type === "userMessage" ? "用户" : "助手";
    const phase = item.type === "agentMessage" && item.phase ? `（${item.phase}）` : "";
    entries.push(`## ${speaker}${phase}\n\n${raw}\n`);
  }
}
